package com.indexer.auth

import scala.collection.mutable
import java.net.{URI, URLDecoder}
import java.nio.charset.StandardCharsets
import java.security.SecureRandom
import java.util.Base64

object OAuthConfig {
  val clientId: String = sys.env.getOrElse("OAUTH_CLIENT_ID", "indexer-service")
  val clientSecret: String = sys.env.getOrElse(
    "OAUTH_CLIENT_SECRET",
    throw new IllegalStateException("OAUTH_CLIENT_SECRET environment variable must be set")
  )
  val authorizationEndpoint: String = sys.env.getOrElse("OAUTH_AUTH_ENDPOINT", "https://auth.internal.corp/authorize")
  val tokenEndpoint: String = sys.env.getOrElse("OAUTH_TOKEN_ENDPOINT", "https://auth.internal.corp/token")

  // Allowed redirect domains loaded from environment
  val allowedRedirectDomains: Set[String] = {
    val raw = sys.env.getOrElse("ALLOWED_REDIRECT_DOMAINS", "indexer.internal.corp,search.internal.corp")
    raw.split(",").map(_.trim.toLowerCase).toSet
  }

  // Base URL for the service
  val serviceBaseUrl: String = sys.env.getOrElse("SERVICE_BASE_URL", "https://indexer.internal.corp")
}

class RedirectValidator {
  import OAuthConfig._

  private val schemeWhitelist = Set("https")

  /**
   * Validates that a redirect_uri is safe to use in OAuth flow.
   * Checks scheme, domain against allowlist, and path safety.
   */
  def validateRedirectUri(redirectUri: String): Either[String, URI] = {
    try {
      val decoded = URLDecoder.decode(redirectUri, StandardCharsets.UTF_8.name())
      val uri = new URI(decoded)

      // Validate scheme
      val scheme = Option(uri.getScheme).map(_.toLowerCase).getOrElse("")
      if (!schemeWhitelist.contains(scheme)) {
        return Left(s"Invalid scheme: $scheme")
      }

      // Validate host against allowed domains using getHost() directly
      val host = Option(uri.getHost).map(_.toLowerCase).getOrElse("")
      if (host.isEmpty) {
        return Left("Missing host in redirect_uri")
      }
      if (!isDomainAllowed(host)) {
        return Left(s"Domain not in allowlist: $host")
      }

      // Validate no path traversal
      val path = Option(uri.getPath).getOrElse("/")
      if (path.contains("..") || path.contains("//")) {
        return Left("Path contains suspicious patterns")
      }

      // Validate no fragment (should not be sent to server)
      if (uri.getFragment != null) {
        return Left("Fragment not allowed in redirect_uri")
      }

      // Validate no userinfo component
      if (uri.getUserInfo != null) {
        return Left("Userinfo not allowed in redirect_uri")
      }

      Right(uri)
    } catch {
      case e: Exception => Left(s"Invalid URI: ${e.getMessage}")
    }
  }

  /**
   * Checks if a given host matches any allowed domain.
   * Supports subdomain matching: foo.bar.allowed.com matches allowed.com
   */
  private def isDomainAllowed(host: String): Boolean = {
    allowedRedirectDomains.exists { allowed =>
      host == allowed || host.endsWith("." + allowed)
    }
  }
}

class OAuthFlowHandler {
  private val validator = new RedirectValidator()
  private val pendingStates = mutable.Map[String, PendingAuth]()
  private val secureRandom = new SecureRandom()

  case class PendingAuth(redirectUri: String, scope: String, timestamp: Long)

  /**
   * Initiates OAuth authorization flow for search index operations.
   * Returns the authorization URL to redirect the user to.
   */
  def initiateAuth(redirectUri: String, scope: String): Either[String, String] = {
    validator.validateRedirectUri(redirectUri) match {
      case Left(error) => Left(s"Invalid redirect_uri: $error")
      case Right(validatedUri) =>
        val state = generateState()
        pendingStates(state) = PendingAuth(
          redirectUri = validatedUri.toString,
          scope = scope,
          timestamp = System.currentTimeMillis()
        )

        val authUrl = buildAuthorizationUrl(state, validatedUri.toString, scope)
        Right(authUrl)
    }
  }

  /**
   * Handles the OAuth callback, validates state, and redirects user.
   * Returns the final redirect URL with the authorization code.
   */
  def handleCallback(code: String, state: String): Either[String, String] = {
    pendingStates.get(state) match {
      case None => Left("Invalid or expired state parameter")
      case Some(pending) =>
        // Check state hasn't expired (5 minute window)
        if (System.currentTimeMillis() - pending.timestamp > 300000) {
          pendingStates.remove(state)
          return Left("State expired")
        }

        pendingStates.remove(state)

        // Reconstruct redirect with code - use the stored URI
        val finalRedirect = appendQueryParam(pending.redirectUri, "code", code)
        Right(finalRedirect)
    }
  }

  private def buildAuthorizationUrl(state: String, redirectUri: String, scope: String): String = {
    s"${OAuthConfig.authorizationEndpoint}?client_id=${OAuthConfig.clientId}" +
      s"&redirect_uri=${java.net.URLEncoder.encode(redirectUri, "UTF-8")}" +
      s"&state=$state&scope=$scope&response_type=code"
  }

  private def appendQueryParam(uri: String, key: String, value: String): String = {
    val separator = if (uri.contains("?")) "&" else "?"
    s"$uri$separator$key=${java.net.URLEncoder.encode(value, "UTF-8")}"
  }

  private def generateState(): String = {
    val bytes = new Array[Byte](32)
    secureRandom.nextBytes(bytes)
    Base64.getUrlEncoder.withoutPadding().encodeToString(bytes)
  }
}

// Search indexing service entry point
object SearchIndexerService {
  val oauthHandler = new OAuthFlowHandler()

  def handleAuthRequest(params: Map[String, String]): Map[String, String] = {
    val redirectUri = params.getOrElse("redirect_uri", OAuthConfig.serviceBaseUrl + "/callback")
    val scope = params.getOrElse("scope", "index:read")

    oauthHandler.initiateAuth(redirectUri, scope) match {
      case Left(error) => Map("error" -> error, "status" -> "400")
      case Right(url) => Map("redirect_url" -> url, "status" -> "302")
    }
  }

  def handleOAuthCallback(params: Map[String, String]): Map[String, String] = {
    val code = params.getOrElse("code", "")
    val state = params.getOrElse("state", "")

    if (code.isEmpty || state.isEmpty) {
      return Map("error" -> "Missing required parameters", "status" -> "400")
    }

    oauthHandler.handleCallback(code, state) match {
      case Left(error) => Map("error" -> error, "status" -> "400")
      case Right(redirect) => Map("redirect_url" -> redirect, "status" -> "302")
    }
  }
}
